package com.englishhero.wall;
import java.sql.Timestamp;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import com.englishhero.identity.SessionPrincipal;
import static com.englishhero.wall.WallDtos.*;
@Service
public class WallNotificationService {
 private final WallMapper mapper;private final WallCommandService commands;
 public WallNotificationService(WallMapper mapper,WallCommandService commands){this.mapper=mapper;this.commands=commands;}
 @Transactional(readOnly=true)public Object list(SessionPrincipal actor,String cursor,int size){long uid=commands.actor(actor);WallRules.size(size);var rows=mapper.sql().query("SELECT n.*,m.status AS message_status,c.status AS comment_status FROM wall_notification n JOIN wall_message m ON m.id=n.message_id LEFT JOIN wall_comment c ON c.id=n.comment_id WHERE n.recipient_id=? AND n.id<? ORDER BY n.id DESC LIMIT ?",(r,n)->{var item=new LinkedHashMap<String,Object>();item.put("id",r.getString("id"));item.put("targetType",r.getString("comment_id")==null?"MESSAGE":"COMMENT");item.put("targetId",r.getString("comment_id")==null?r.getString("message_id"):r.getString("comment_id"));item.put("messageId",r.getString("message_id"));item.put("action",r.getString("action"));item.put("authorReason",r.getString("author_reason"));item.put("excerpt",r.getString("excerpt"));item.put("createdAt",r.getTimestamp("created_at").toInstant());var read=r.getTimestamp("read_at");item.put("readAt",read==null?null:read.toInstant());item.put("canOpen",r.getString("message_status").equals("VISIBLE")&&(r.getString("comment_id")==null||"VISIBLE".equals(r.getString("comment_status"))));return item;},uid,WallRules.cursor(cursor),size+1);boolean more=rows.size()>size;var items=rows.stream().limit(size).toList();var result=new LinkedHashMap<String,Object>();result.put("items",items);result.put("hasMore",more);result.put("nextCursor",more?items.getLast().get("id"):null);result.put("unreadCount",mapper.sql().queryForObject("SELECT COUNT(*) FROM wall_notification WHERE recipient_id=? AND read_at IS NULL",Long.class,uid));result.put("readBoundary",mapper.sql().queryForObject("SELECT COALESCE(MAX(id),0) FROM wall_notification WHERE recipient_id=?",String.class,uid));return result;}
 @Transactional(isolation=Isolation.READ_COMMITTED)public Object read(SessionPrincipal actor,String id){long uid=commands.actor(actor),nid=WallRules.id(id,"id");if(mapper.sql().queryForObject("SELECT COUNT(*) FROM wall_notification WHERE recipient_id=? AND id=?",Integer.class,uid,nid)==0)throw WallRules.missing();mapper.sql().update("UPDATE wall_notification SET read_at=COALESCE(read_at,?) WHERE recipient_id=? AND id=?",Timestamp.from(commands.clock.instant()),uid,nid);return Map.of("read",true);}
 @Transactional(isolation=Isolation.READ_COMMITTED)public Object readAll(SessionPrincipal actor,Map<String,String> input){long uid=commands.actor(actor);String boundary=input==null?null:input.get("throughId");long end="0".equals(boundary)?0:WallRules.id(boundary,"throughId");mapper.sql().update("UPDATE wall_notification SET read_at=COALESCE(read_at,?) WHERE recipient_id=? AND id<=? AND read_at IS NULL",Timestamp.from(commands.clock.instant()),uid,end);return Map.of("read",true);}
}
